from pathlib import Path
r=Path(Path('/tmp/penkra-policy-input-path').read_text());repo=Path.cwd();base=(repo/'docs/qa/hosted-view-visibility-regression/head/harness/main-native-final.ts').read_text();prefix=base[:base.index(' const os:any[]=[];')]
prefix=prefix.replace("import {spawnSync}","import {spawn,spawnSync}")
prefix="import {AppTabObserver} from '../apps/desktop/src/appTabObserver';import {AppCommandPipeServer} from '../apps/desktop/src/appCommandPipeServer';import {executePenkraExecCommand} from '../apps/server/src/appRuntimeCli';\n"+prefix
prefix=prefix.replace("res.end('<html><body style=\"background:#d0f0c0\"><h2>QA live hosted page</h2><b id=\"counter\"></b><script>window.counter=0;setInterval(()=>document.getElementById(\"counter\").textContent=++window.counter,50)</script></body></html>')","res.end(fs.readFileSync('qa/probe.html'))")
prefix=prefix.replace("counter:window.counter","counter:window.counter,scrollY:window.scrollY")
prefix=prefix.replace("async function run(){await app.whenReady();","async function run(){await app.whenReady();process.env.QA_BYPASS_TAB_GUARD='1';const helperLog=fs.openSync(path.join(evidence,'helper.log'),'a');const helperProcess=spawn('/usr/bin/osascript',['-l','JavaScript','qa/helper.js'],{env:process.env,stdio:['ignore',helperLog,helperLog]});for(let i=0;i<100&&!fs.existsSync(path.join(root,'helper-state.json'));i++)await pause(50);if(!fs.existsSync(path.join(root,'helper-state.json')))throw new Error('helper startup');")
body=r'''
 const requestedState=process.env.QA_STATE!,policy=process.env.QA_POLICY!;let second:BrowserWindow|null=null,targetId:number|null=null;const samples:any[]=[];const trials:any[]=[];let serial=0;
 function geometry(){const helper=JSON.parse(fs.readFileSync(path.join(root,'helper-state.json'),'utf8'));const out=spawnSync('python3',['qa/cg-window-list.py',String(process.pid),String(helper.pid)],{encoding:'utf8'});if(out.status!==0)throw new Error(out.stderr);const d=JSON.parse(out.stdout);if(targetId===null)targetId=d.windows.find((w:any)=>w.pid===process.pid&&w.bounds.X===70&&w.bounds.Y===70&&w.bounds.Width===1000&&w.bounds.Height===700)?.windowId??null;return{...d,targetWindow:d.windows.find((w:any)=>w.windowId===targetId)??null,helper}}
 const page=host.target('qa-A','d2');
 const originalSend=page.debugger.sendCommand.bind(page.debugger);(page.debugger as any).sendCommand=async(method:string,params:any,sessionId:any)=>{const callId=++serial,start=performance.now();trace('cdp-start',{callId,method,params,sessionId});try{const result=await originalSend(method,params,sessionId);trace('cdp-end',{callId,method,durationMs:performance.now()-start});return result}catch(e){trace('cdp-error',{callId,method,durationMs:performance.now()-start,error:String(e)});throw e}};
 page.on('console-message',(event:any,level:any,message:any)=>{const text=event.message??message??'';if(text.startsWith('QA_PAGE_EVENT '))trace('page-event',JSON.parse(text.slice(14)))});
 const observer=new AppTabObserver({resolve:(tabId,document,surfaceId)=>({descriptor:host.list().find(t=>t.id===tabId)!,document,webContents:host.target(tabId,document),isPresented:()=>shell.isVisible()&&!shell.isMinimized()&&host.ownerWindowId(tabId)===owner&&host.isVisible(tabId),canDeliverPointerInput:()=>host.canDeliverPointerInput(tabId)})});
 for(const name of ['click','type','scroll','snapshot'] as const){const original=(observer as any)[name].bind(observer);(observer as any)[name]=async(...args:any[])=>{const start=performance.now();trace('observer-phase-start',{name});try{return await original(...args)}finally{trace('observer-phase-end',{name,durationMs:performance.now()-start})}}}
 const commandServer=new AppCommandPipeServer({path:path.join(root,'qa-home','commands.sock'),token:'qa-fixture-command-token',catalog:{} as any,broker:{} as any,tabs:host,activate:async()=>({}),presentation:()=>({state:host.isVisible('qa-A')?'active':'background'}),observationSurface:()=>owner,observer,providerCredentialVault:{} as any});await commandServer.start();
 const context={spaceId:'qa-space',folderId:'qa-folder',threadId:'qa-thread',callerTurnId:'qa-turn',cwd:evidence};
 async function execute(command:string){const startedEpochMs=Date.now(),start=performance.now();trace('command-start',{command,startedEpochMs});try{const result=await executePenkraExecCommand({command},context,commandServer.environment);const row={returned:true,ok:true,startedEpochMs,endedEpochMs:Date.now(),durationMs:performance.now()-start,result};trace('command-end',row);return row}catch(e:any){const row={returned:true,ok:false,startedEpochMs,endedEpochMs:Date.now(),durationMs:performance.now()-start,error:{message:e.message,code:e.code,outcome:e.outcome}};trace('command-end',row);return row}}
 async function sample(){return{...await state(),shellFullScreen:shell.isFullScreen(),secondFullScreen:second?.isFullScreen()??false,secondSimpleFullScreen:second?.isSimpleFullScreen()??false,backgroundThrottling:page.getBackgroundThrottling(),geometry:geometry()}}
 async function sampleSave(label:string){const row={label,...await sample()};samples.push(row);fs.writeFileSync(path.join(evidence,'samples.json'),JSON.stringify(samples,null,2));trace('state-sample',row);return row}
 async function helper(action:string,extra:any={}){fs.writeFileSync(path.join(root,'helper-control.json'),JSON.stringify({action,serial:Date.now(),...extra}));await pause(500)}
 shell.on('focus',()=>{if(host)void host.focusWindow(owner).catch(e=>trace('host-focus-failed',{error:String(e)}))});
 async function reset(){await helper('hide');app.show();shell.restore();shell.show();shell.setBounds({x:70,y:70,width:1000,height:700});app.focus({steal:true});shell.moveTop();shell.focus();await host.setWindowVisibility(owner,true);await host.presentInWindow({tabId:'qa-A',folderId:'qa-folder',threadId:'qa-thread',windowId:owner,bounds:{x:601,y:44,width:399,height:656},animate:false});await pause(800)}
 async function full(win:BrowserWindow,value:boolean){for(let i=0;i<4;i++){if(value){app.focus({steal:true});win.show();win.moveTop();win.focus();await pause(350)}trace('fullscreen-request',{id:win.id,value,attempt:i});win.setFullScreen(value);await pause(3500);if(win.isFullScreen()===value){await pause(700);return}}throw new Error('native fullscreen timeout')}
 await reset();await sampleSave('visible-baseline');
 const snap=await execute('penkra tabs snapshot --tab-id qa-A --document d2');const refs:any=(snap as any).result?.refs??{};const find=(name:string)=>Object.entries(refs).find(([k,v]:any)=>v.name===name)?.[0];if(!find('Click probe')||!find('Text probe'))throw new Error('snapshot refs absent');
 caseId='enter-'+requestedState;
 if(requestedState==='space'){second=new BrowserWindow({width:900,height:700,show:false});await second.loadURL('data:text/html,<html><body>QA second native full-screen Space</body></html>');await full(shell,true);await helper('activate',{x:1300,y:100,width:250,height:250});await pause(1500);second.showInactive();await full(second,true);shell.focus();await pause(1600);await sampleSave('first-space-front');second.focus();await pause(1600)}
 if(requestedState==='minimized'){shell.minimize();await pause(900)}
 if(requestedState==='apphide'){app.focus({steal:true});shell.focus();await pause(150);trace('native-app-hide-request');app.hide();await pause(900)}
 if(requestedState==='covered'){const g=geometry(),b=g.targetWindow?.bounds;if(!b)throw new Error('target geometry missing');await helper('cover',{x:b.X,y:b.Y,width:b.Width,height:b.Height});await pause(700)}
 await sampleSave('state-before-trials');
 for(let repetition=0;repetition<3;repetition++)for(const action of ['click','type','scroll']){
  const id=`${policy}-${requestedState}-${action}-${repetition}`;caseId=id;trace('reset-page-start');await page.executeJavaScript(`window.qaReset(${JSON.stringify(id)})`,false);trace('reset-page-end');await pause(250);const before=await sample();const step:any=action==='click'?{action,ref:find('Click probe')}:action==='type'?{action,ref:find('Text probe'),text:id}:{action,document:'d2',deltaY:400};
  const response=await execute(`penkra tabs act --input '${JSON.stringify({tabId:'qa-A',steps:[step]})}'`);const immediate=await page.executeJavaScript('window.qaState()',false);await pause(1100);const afterPage=await page.executeJavaScript('window.qaState()',false);const after=await sample();const event=afterPage.events.find((v:any)=>v.kind===(action==='type'?'input':action)&&v.caseId===id);const row={policy,requestedState,id,repetition,action,before,response,immediate,afterPage,after,event:event??null,pageDelayMs:event?event.epochMs-response.startedEpochMs:null};trials.push(row);fs.writeFileSync(path.join(evidence,'trials.json'),JSON.stringify(trials,null,2));trace('trial-completed',row);
 }
 caseId='return';trace('return-request',{requestedState});
 if(requestedState==='space')shell.focus();if(requestedState==='minimized')shell.restore();if(requestedState==='apphide'){app.show();shell.show();shell.focus()}if(requestedState==='covered')await helper('hide');
 const returnSamples=[];for(let i=0;i<12;i++){const start=performance.now(),row=await sample();returnSamples.push({...row,atMs:start});if(row.geometry.targetWindow?.onScreen){const image=spawnSync('/usr/sbin/screencapture',['-x','-l',String(targetId),path.join(evidence,`return-${i}.png`)],{encoding:'utf8'});trace('return-window-capture',{i,status:image.status,stderr:image.stderr})}await pause(30)}fs.writeFileSync(path.join(evidence,'return-samples.json'),JSON.stringify(returnSamples,null,2));
 if(second){await full(second,false);second.hide();await full(shell,false);second.destroy()}
 caseId='cleanup';await helper('quit');observer.dispose();await commandServer.dispose();host.closeAll();shell.destroy();backend.closeAllConnections();web.closeAllConnections();await Promise.all([new Promise<void>(r=>backend.close(()=>r())),new Promise<void>(r=>web.close(()=>r()))]);helperProcess.kill();app.exit(0);
}
run().catch(error=>{console.error(error);fs.writeFileSync(path.join(evidence,'failure.txt'),error.stack??String(error));app.exit(1)});
'''
for policy in ['A','B']:
 q=r/policy/'source/qa';(q/'main.ts').write_text(prefix+body)
 helper=(q/'helper.js').read_text().replace('i<2400','i<18000').replace("c.action==='show'","c.action==='activate'")
 helper=helper.replace("if(c.action==='hide')", "if(c.action==='cover'){win.collectionBehavior=$.NSWindowCollectionBehaviorCanJoinAllSpaces;win.level=$.NSFloatingWindowLevel;win.setFrameDisplay($.NSMakeRect(c.x||0,c.y||0,c.width||1200,c.height||800),true);win.orderFrontRegardless;}if(c.action==='hide')")
 (q/'helper.js').write_text(helper)
 build=(q/'build.mjs').read_text();build=build.replace("setup(build){","setup(build){build.onResolve({filter:/\\.md\\?raw$/},args=>({path:path.resolve(args.resolveDir,args.path.slice(0,-4)),namespace:'raw-md'}));build.onLoad({filter:/.*/,namespace:'raw-md'},async args=>({contents:'export default '+JSON.stringify(await Bun.file(args.path).text()),loader:'js'}));")
 (q/'build.mjs').write_text(build)
print(r)
